INSERT INTO public.realworld_lessons (id, language_id, unit, "order", data)
VALUES ('vi-survival-1', 'vi', 1, 1, '{"id":"vi-survival-1","language":"vi","unit":1,"order":1,"titleVi":"Chào và giới thiệu","titleEn":"Say hello and introduce yourself","canDoVi":"Tôi có thể nói tên của mình khi gặp người mới.","scenario":{"settingVi":"Bạn gặp một người mới ở lớp.","roles":["Người học","Bạn cùng lớp"]},"dialogue":[{"speaker":"A","text":"Xin chào, tôi là Lan.","vi":"Chào, tôi là Lan."},{"speaker":"B","text":"Rất vui được gặp bạn, Lan.","vi":"Rất vui được gặp bạn, Lan."}],"chunks":[{"text":"Xin chào, tôi là ...","vi":"Chào, tôi là ...","useWhenVi":"khi tự giới thiệu","vietnameseLearnerCueVi":"Nói tên bạn."},{"text":"Rất vui được gặp bạn.","vi":"Rất vui được gặp bạn.","useWhenVi":"khi mới gặp ai","vietnameseLearnerCueVi":"Dùng sau lời chào."},{"text":"Bạn tên là gì?","vi":"Bạn tên là gì?","useWhenVi":"khi hỏi tên","vietnameseLearnerCueVi":"Hỏi tên."}],"contextCue":{"titleVi":"Bắt đầu câu chuyện","bodyVi":"Tự tin nói xin chào."},"comprehension":{"promptVi":"Đâu là cách nói Xin chào?","options":["Xin chào, tôi là Lan.","Trời hôm nay đẹp."],"correctAnswer":"Xin chào, tôi là Lan.","explanationVi":"Xin chào là câu chào cơ bản."},"production":{"promptVi":"Bạn hãy tự giới thiệu bản thân.","requiredSlots":["tên của bạn"],"exemplar":"Xin chào, tôi là Mai. Rất vui được gặp bạn.","rejectExactModelCopy":true},"retrieval":{"promptVi":"Hãy gõ lại câu dùng để tự giới thiệu.","cueVi":"Xin chào, tôi là ...","acceptedPatterns":[{"requiredFragments":["xin chào","tôi là"],"rejectedNames":["lan","mai"]}],"answerHintVi":"Gợi ý: bắt đầu bằng \"Xin chào, tôi là ...\""},"selfReview":["Phát âm rõ ràng","Dùng đúng tên"]}'::jsonb)
