INSERT INTO public.realworld_lessons (id, language_id, unit, "order", data)
VALUES ('th-survival-1', 'th', 1, 1, '{"id":"th-survival-1","language":"th","unit":1,"order":1,"titleVi":"Chào và giới thiệu","titleEn":"Say hello and introduce yourself","canDoVi":"Tôi có thể nói tên của mình khi gặp người mới.","scenario":{"settingVi":"Bạn gặp một người mới ở lớp.","roles":["Người học","Bạn cùng lớp"]},"dialogue":[{"speaker":"A","text":"สวัสดี ฉันชื่อหลาน","vi":"Chào, tôi là Lan."},{"speaker":"B","text":"ยินดีที่ได้รู้จัก หลาน","vi":"Rất vui được gặp bạn, Lan."}],"chunks":[{"text":"สวัสดี ฉันชื่อ ...","vi":"Chào, tôi là ...","useWhenVi":"khi tự giới thiệu","vietnameseLearnerCueVi":"Nói tên bạn."},{"text":"ยินดีที่ได้รู้จัก","vi":"Rất vui được gặp bạn.","useWhenVi":"khi mới gặp ai","vietnameseLearnerCueVi":"Dùng sau lời chào."},{"text":"คุณชื่ออะไร?","vi":"Bạn tên là gì?","useWhenVi":"khi hỏi tên","vietnameseLearnerCueVi":"Hỏi tên."}],"contextCue":{"titleVi":"Bắt đầu câu chuyện","bodyVi":"Tự tin nói xin chào."},"comprehension":{"promptVi":"Đâu là cách nói Xin chào?","options":["สวัสดี ฉันชื่อหลาน","ฉันหิวข้าว"],"correctAnswer":"สวัสดี ฉันชื่อหลาน","explanationVi":"สวัสดี là xin chào."},"production":{"promptVi":"Bạn hãy tự giới thiệu bản thân.","requiredSlots":["tên của bạn"],"exemplar":"สวัสดี ฉันชื่อไม ยินดีที่ได้รู้จัก","rejectExactModelCopy":true},"retrieval":{"promptVi":"Hãy gõ lại câu dùng để tự giới thiệu.","cueVi":"สวัสดี ฉันชื่อ ...","acceptedPatterns":[{"requiredFragments":["สวัสดี","ฉันชื่อ"],"rejectedNames":["หลาน","ไม"]}],"answerHintVi":"Gợi ý: bắt đầu bằng \"สวัสดี ฉันชื่อ ...\""},"selfReview":["Phát âm rõ ràng","Dùng đúng tên"]}'::jsonb)
