INSERT INTO public.realworld_lessons (id, language_id, unit, "order", data)
VALUES ('ar-survival-1', 'ar', 1, 1, '{"id":"ar-survival-1","language":"ar","unit":1,"order":1,"titleVi":"Chào và giới thiệu","titleEn":"Say hello and introduce yourself","canDoVi":"Tôi có thể nói tên của mình khi gặp người mới.","scenario":{"settingVi":"Bạn gặp một người mới ở lớp.","roles":["Người học","Bạn cùng lớp"]},"dialogue":[{"speaker":"A","text":"مرحباً، أنا لان.","vi":"Chào, tôi là Lan."},{"speaker":"B","text":"تشرفنا، لان.","vi":"Rất vui được gặp bạn, Lan."}],"chunks":[{"text":"مرحباً، أنا ...","vi":"Chào, tôi là ...","useWhenVi":"khi tự giới thiệu","vietnameseLearnerCueVi":"Nói tên bạn."},{"text":"تشرفنا.","vi":"Rất vui được gặp bạn.","useWhenVi":"khi mới gặp ai","vietnameseLearnerCueVi":"Dùng sau lời chào."},{"text":"ما اسمك؟","vi":"Bạn tên là gì?","useWhenVi":"khi hỏi tên","vietnameseLearnerCueVi":"Hỏi tên."}],"contextCue":{"titleVi":"Bắt đầu câu chuyện","bodyVi":"Tự tin nói xin chào."},"comprehension":{"promptVi":"Đâu là cách nói Xin chào?","options":["مرحباً، أنا لان.","أنا أحب التفاح."],"correctAnswer":"مرحباً، أنا لان.","explanationVi":"مرحباً là xin chào."},"production":{"promptVi":"Bạn hãy tự giới thiệu bản thân.","requiredSlots":["tên của bạn"],"exemplar":"مرحباً، أنا ماي. تشرفنا.","rejectExactModelCopy":true},"retrieval":{"promptVi":"Hãy gõ lại câu dùng để tự giới thiệu.","cueVi":"مرحباً، أنا ...","acceptedPatterns":[{"requiredFragments":["مرحباً","أنا"],"rejectedNames":["لان","ماي"]}],"answerHintVi":"Gợi ý: bắt đầu bằng \"مرحباً، أنا ...\""},"selfReview":["Phát âm rõ ràng","Dùng đúng tên"]}'::jsonb)
